rows={x.split('|')[0]:x.split('|')[1:] for x in ROWS.splitlines()}
for i,a in enumerate(D['areas']):
    r=rows[a['id']];assert len(r)==10
    for li,lang in enumerate(('fr','en')):
        # Keep D04 for the separate causal-inference task. D05 is a new PA case.
        lab=a['caseLab'][lang];lab['artifacts']=[x for x in lab['artifacts'] if 'D05' not in x['type']]
        example=a['appliedLesson'][lang]['example']
        lab['artifacts'].append({'type':'TRANSFER · D05','title':('Cas de transfert' if li==0 else 'Transfer case'),'date':'15 Oct 2026','body':'D05: '+example,'signal':'open'})
        opts=[r[2+2*j+li] for j in range(4)];shift=i%4;opts=opts[shift:]+opts[:shift]
        a['masteryQuestions'][lang][2]={'id':f'{a["id"]}-R9-transfer','q':f'C-{a["id"]} · '+r[li],'options':opts,'answer':(-shift)%4,'why':example}
D['assessmentRevision']='r9-transfer-cases'
(P/'data.json').write_text(json.dumps(D,ensure_ascii=False,separators=(',',':')))
print('Added 31 bilingual D05 transfer cases and 31 distinct mastery questions per language.')
